function exportWithCompleteOriginalCompetitionLogo(){
  document.querySelectorAll('.competition-logo').forEach(logo=>logo.remove());
  const logos=[...document.querySelectorAll('.competition-logo img')].map(item=>{const logo=new Image();logo.src=item.dataset.exportSource||item.currentSrc||item.src;return logo;});
  const ready=logo=>new Promise(resolve=>{if(logo.complete&&logo.naturalWidth)return resolve();logo.addEventListener('load',resolve,{once:true});logo.addEventListener('error',resolve,{once:true});});
  Promise.all(logos.map(ready)).then(()=>{
    const originalToDataURL=HTMLCanvasElement.prototype.toDataURL;
    const originalRestore=CanvasRenderingContext2D.prototype.restore;
    let competitionLogoRestores=0;
    CanvasRenderingContext2D.prototype.restore=function(){
      originalRestore.call(this);
      if(this.canvas?.width===1800&&this.canvas?.height===1250&&competitionLogoRestores<2){
        const logo=logos[competitionLogoRestores++];
        if(logo?.naturalWidth){
          const center=competitionLogoRestores===2?1225:575;
          this.save();
          this.imageSmoothingEnabled=true;
          this.fillStyle='#fff';
          this.fillRect(center-32,2,64,68);
          this.drawImage(logo,center-30,6,60,60);
          originalRestore.call(this);
        }
      }
    };
    HTMLCanvasElement.prototype.toDataURL=function(...args){
      if(this.width===1800&&this.height===1250){
        const context=this.getContext('2d');
        context.imageSmoothingEnabled=true;
        logos.forEach((logo,index)=>{
          if(!logo.naturalWidth)return;
          const center=index?1225:575;
          context.save();
          context.fillStyle='#fff';
          context.fillRect(center-32,2,64,68);
          context.drawImage(logo,center-30,6,60,60);
          context.restore();
        });
      }
      return originalToDataURL.apply(this,args);
    };
    try{imageExportWithOriginalCompetitionLogos();}finally{setTimeout(()=>{HTMLCanvasElement.prototype.toDataURL=originalToDataURL;CanvasRenderingContext2D.prototype.restore=originalRestore;},8000);}
  });
}
setTimeout(()=>{const button=document.querySelector('#imageBtn');if(button)button.onclick=exportWithCompleteOriginalCompetitionLogo;},20);
