const baseImageWithoutCompetitionIcons=HTMLCanvasElement.prototype.toDataURL;
HTMLCanvasElement.prototype.toDataURL=function(...args){
  if(this.width===1800&&this.height===1250){
    const context=this.getContext('2d');
    context.save();
    context.fillStyle='#fff';
    context.fillRect(538,0,74,72);
    context.fillRect(1188,0,74,72);
    context.restore();
  }
  return baseImageWithoutCompetitionIcons.apply(this,args);
};

