const createStableSelectedImageWithProjectHeader = createStableSelectedImage;
createStableSelectedImage = async function(){
  const originalFillText = CanvasRenderingContext2D.prototype.fillText;
  const competition = document.querySelector('.competition-title summary')?.textContent?.trim() || document.querySelector('.competition-title')?.textContent?.trim() || '';
  const season = document.querySelector('.season-menu summary')?.textContent?.trim() || '';
  const day = document.querySelector('.match-day')?.textContent?.trim() || '';
  const date = document.querySelector('.match-date')?.textContent?.trim() || '';
  const venue = document.querySelector('#venueField')?.textContent?.trim() || '';
  const officials = [...document.querySelectorAll('.official-detail')].map(item => item.textContent.trim());
  CanvasRenderingContext2D.prototype.fillText = function(text,x,y,maxWidth){
    if (x === 900 && y === 40) {
      this.save();
      this.textAlign = 'center'; this.fillStyle = '#111'; this.font = 'bold 22px Arial';
      originalFillText.call(this, `${competition}${season ? ` · STAGIONE SPORTIVA ${season}` : ''}`, 900, 32, maxWidth);
      this.font = 'bold 15px Arial';
      originalFillText.call(this, [day, date].filter(Boolean).join('     '), 900, 57, maxWidth);
      this.font = '14px Arial';
      originalFillText.call(this, venue, 900, 79, maxWidth);
      this.font = '13px Arial';
      officials.forEach((official,index) => originalFillText.call(this, official, [740,900,1060][index] || 900, 102, 210));
      this.restore();
      return;
    }
    if (x === 900 && y === 68) return;
    return originalFillText.call(this,text,x,y,maxWidth);
  };
  try { return await createStableSelectedImageWithProjectHeader(); }
  finally { CanvasRenderingContext2D.prototype.fillText = originalFillText; }
};
