function applyRegulationMinutes(select){
  if(!select)return;
  addRecoveryPicker(select);
  if(select.dataset.regulationMinutes==='true')return;
  const current=select.value;
  const minutes=Array.from({length:90},(_,index)=>String(index+1));
  select.innerHTML=minutes.map(minute=>`<option value="${minute}">${minute}'</option>`).join('');
  if(minutes.includes(current))select.value=current;
  select.dataset.regulationMinutes='true';
}
function addRecoveryPicker(select){
  if(select.parentElement?.querySelector('.recovery-picker'))return;
  const recovery=document.createElement('label');
  recovery.className='recovery-picker';
  recovery.textContent='Recupero ';
  const picker=document.createElement('select');
  picker.className='recovery-select';
  picker.innerHTML=`<option value="">+0'</option>${Array.from({length:20},(_,index)=>`<option value="+${index+1}">+${index+1}'</option>`).join('')}`;
  recovery.append(picker);
  select.insertAdjacentElement('afterend',recovery);
  picker.addEventListener('change',()=>{
    if(!picker.value)return;
    const base=String(select.value||'1').split('+')[0];
    const value=`${base}${picker.value}`;
    let option=[...select.options].find(item=>item.value===value);
    if(!option){option=new Option(`${value}'`,value);select.append(option);}
    select.value=value;
  });
  select.addEventListener('change',()=>{if(!String(select.value).includes('+'))picker.value='';});
}
document.addEventListener('pointerdown',event=>applyRegulationMinutes(event.target.closest('.minute-select')),true);
document.addEventListener('focusin',event=>applyRegulationMinutes(event.target.closest('.minute-select')),true);
new MutationObserver(()=>document.querySelectorAll('.minute-select').forEach(applyRegulationMinutes)).observe(document.body,{childList:true,subtree:true});
